import Foundation
import Testing
@testable import CmuxSyntaxHighlighting

/// The objdump listing parser (AsmListingParser, a port of Compiler Explorer's binary-asm parser) and
/// its pc/line tables. Fixtures are GNU objdump 2.47 and llvm-objdump 23 output for the programs in
/// Tests/Fixtures/AsmListing/src (ours), regenerated by its build.sh.
@Suite("Assembly listings")
struct AsmListingTests {
    static let fixtures = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Fixtures/AsmListing")

    static func fixture(_ name: String) throws -> String {
        try String(contentsOf: fixtures.appendingPathComponent(name), encoding: .utf8)
    }

    static func parse(_ name: String) throws -> AsmListing {
        AsmListingParser.parse(try fixture(name))
    }

    /// (pc, symbol, offset, section) of every instruction, the part every variant of one program agrees on.
    static func places(_ listing: AsmListing) -> [String] {
        listing.instructions.map { "\(String($0.pc, radix: 16)) \($0.symbol ?? "-")+\($0.offset) \($0.section ?? "-")" }
    }

    // MARK: GNU objdump

    @Test func gnuCodeListing() throws {
        let listing = try Self.parse("gnu-rv32-code.dis")
        #expect(listing.flavor == .gnu)
        #expect(listing.fileFormat == "elf32-littleriscv")
        #expect(listing.xlen == 32)
        #expect(listing.instructions.count == 24)
        #expect(listing.labels.map(\.name) == ["_start", "after_gap", "sum"])
        let li = try #require(listing.instruction(forPC: 0x8000_0004))
        #expect(li.text == "li\ta0,0")
        #expect(li.encoding == 0x4501)
        #expect(li.size == 2)
        #expect(li.symbol == "_start")
        #expect(li.offset == 4)
        #expect(li.section == ".text")
        #expect(li.isCode)
        let lui = try #require(listing.instruction(forPC: 0x8000_0000))
        #expect(lui.encoding == 0x8000_4137)
        #expect(lui.size == 4)
        // The listing's own line: 0-based, as an editor counts them.
        let lines = try Self.fixture("gnu-rv32-code.dis").components(separatedBy: "\n")
        #expect(lines[li.line].hasPrefix("80000004:"))
        #expect(listing.line(forPC: 0x8000_0004) == li.line)
        #expect(listing.pc(forLine: li.line) == 0x8000_0004)
        #expect(listing.pc(forLine: li.line + 1) == 0x8000_0006)
        // A branch's target and its symbol, from objdump's `<sym+off>`.
        let bnez = try #require(listing.instruction(forPC: 0x8000_000c))
        #expect(bnez.target == 0x8000_0008)
        #expect(bnez.targetSymbol == "_start")
        let addi = try #require(listing.instruction(forPC: 0x8000_0052))
        #expect(addi.text == "addi\ta1,a1,26 # 80000068 <table>")
        #expect(addi.target == 0x8000_0068)
        #expect(addi.targetSymbol == "table")
        #expect(addi.symbol == "sum" && addi.offset == 4)
        // `...` (zeros left out) is kept as a line of its own.
        #expect(listing.elidedLines.count == 1)
        // The label after the gap starts its own symbol.
        let ebreak = try #require(listing.instruction(forPC: 0x8000_004c))
        #expect(ebreak.symbol == "after_gap" && ebreak.offset == 0)
    }

    @Test func noLineIsAnInstructionUnlessItIsOne() throws {
        let text = try Self.fixture("gnu-rv32-code.dis")
        let listing = AsmListingParser.parse(text)
        let lines = text.components(separatedBy: "\n")
        for (index, line) in lines.enumerated() {
            let isInstruction = line.range(of: #"^[0-9a-f]{8}:\t"#, options: .regularExpression) != nil
            #expect((listing.instruction(atLine: index) != nil) == isInstruction, "line \(index): \(line)")
        }
    }

    @Test func gnuRV64() throws {
        let listing = try Self.parse("gnu-rv64-code.dis")
        #expect(listing.fileFormat == "elf64-littleriscv")
        #expect(listing.xlen == 64)
        let jal = try #require(listing.instruction(forPC: 0x8000_0012))
        #expect(jal.encoding == 0x0400_00ef)
        #expect(jal.target == 0x8000_0052)
        #expect(jal.targetSymbol == "sum")
    }

    @Test func gnuAllSectionsMarksDataAndPrefersCode() throws {
        let listing = try Self.parse("gnu-rv32-all.dis")
        let sections = Set(listing.instructions.compactMap(\.section))
        #expect(sections.isSuperset(of: [".text", ".rodata.cst32", ".data", ".riscv.attributes", ".comment"]))
        for inst in listing.instructions {
            #expect(inst.isCode == (inst.section == ".text"), "\(inst.section ?? "-") \(String(inst.pc, radix: 16))")
        }
        // `.riscv.attributes` and `.comment` start at 0, as does .debug_*: a pc there is data.
        let table = try #require(listing.instruction(forPC: 0x8000_0068))
        #expect(!table.isCode && table.symbol == "table")
        // A 48-bit `.insn` is printed as three 16-bit parcels, low parcel first.
        let wide = try #require(listing.instructions.first { $0.text.hasPrefix(".insn\t6, 0x5f307032635f") })
        #expect(wide.encoding == 0x5f30_7032_635f)
        #expect(wide.size == 6)
    }

    @Test func codeWinsAReverseLookupOverData() {
        let text = """
        a.elf:     file format elf32-littleriscv


        Disassembly of section .comment:

        00000000 <.comment>:
           0:\t3e41                \tjal\tfffffb90 <x>

        Disassembly of section .text:

        00000000 <_start>:
           0:\t00000013          \tnop
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instructions.count == 2)
        let found = listing.instruction(forPC: 0)
        #expect(found?.section == ".text")
        #expect(found?.isCode == true)
        #expect(listing.line(forPC: 0) == 11)
    }

    @Test func everyGnuVariantAgreesOnThePlaces() throws {
        let code = try Self.parse("gnu-rv32-code.dis")
        let expected = Self.places(code)
        for name in ["gnu-rv32-noraw.dis", "gnu-rv32-l.dis", "gnu-rv32-S.dis",
                     "gnu-rv32-numeric-noaliases.dis", "gnu-rv32-prefix.dis", "gnu-rv32-prefix-raw.dis"] {
            let other = try Self.parse(name)
            #expect(Self.places(other) == expected, "\(name)")
        }
        // Encodings agree wherever both show raw bytes.
        for name in ["gnu-rv32-l.dis", "gnu-rv32-S.dis", "gnu-rv32-prefix-raw.dis",
                     "gnu-rv32-numeric-noaliases.dis"] {
            let other = try Self.parse(name)
            #expect(other.instructions.map(\.encoding) == code.instructions.map(\.encoding), "\(name)")
            #expect(other.instructions.map(\.size) == code.instructions.map(\.size), "\(name)")
        }
        // `-z` shows the zeros `...` left out: every place of -d is in it, plus the zeros.
        let zeros = try Self.parse("gnu-rv32-z.dis")
        #expect(Set(expected).isSubset(of: Set(Self.places(zeros))))
        #expect(zeros.instructions.count > code.instructions.count)
        #expect(zeros.elidedLines.isEmpty)
    }

    @Test func noRawInstructionsStillHaveSizes() throws {
        let listing = try Self.parse("gnu-rv32-noraw.dis")
        let li = try #require(listing.instruction(forPC: 0x8000_0004))
        #expect(li.encoding == nil)
        #expect(li.text == "li\ta0,0")
        #expect(li.size == 2)  // from the next address
        #expect(listing.instruction(forPC: 0x8000_0000)?.size == 4)
        // A mnemonic made of hex digits is not raw bytes: bytes come in pairs.
        let add = try #require(listing.instruction(forPC: 0x8000_0024))
        #expect(add.text == "add\ta1,a2,a3")
        #expect(add.encoding == nil)
    }

    @Test func visualizedJumpsAreNotPartOfTheBytes() throws {
        // Up to the zero gap (`--stop-address`): the same instructions as -d, arrows left out.
        let code = try Self.parse("gnu-rv32-code.dis")
        let jumps = try Self.parse("gnu-rv32-jumps-start.dis")
        let start = code.instructions.filter { $0.pc < 0x8000_002c }
        #expect(Self.places(jumps) == start.map { "\(String($0.pc, radix: 16)) \($0.symbol ?? "-")+\($0.offset) \($0.section ?? "-")" })
        #expect(jumps.instructions.map(\.encoding) == start.map(\.encoding))
        let addi = try #require(jumps.instruction(forPC: 0x8000_0008))
        #expect(addi.encoding == 0x050d)
        #expect(addi.text == "addi\ta0,a0,3")
        // The whole of .text: binutils then prints it as `.word`s (its own quirk with the gap); still
        // read as 4-byte units at their addresses, under their symbols.
        let words = try Self.parse("gnu-rv32-jumps.dis")
        let word = try #require(words.instruction(forPC: 0x8000_0008))
        #expect(word.encoding == 0x12fd_050d && word.size == 4 && word.text == ".word\t0x12fd050d")
        #expect(words.instruction(forPC: 0x8000_0052)?.symbol == "sum")
    }

    @Test func sourceInterleavedListingsKeepSourceLinesOut() throws {
        // -S prints the asm source, whose `1:  j 1b` looks like an instruction at address 1.
        let listing = try Self.parse("gnu-rv32-S.dis")
        #expect(listing.instruction(forPC: 1) == nil)
        #expect(listing.instructions.allSatisfy { $0.pc >= 0x8000_0000 })
    }

    @Test func sourceTextWithTabsStaysSourceText() {
        // An -S source line written with tabs (`1:\tj\t1b`) has a tab like an instruction; its
        // address goes back, and objdump writes a section's addresses in order.
        let text = """
        Disassembly of section .text:

        80000000 <_start>:
        80000000:\t00000013          \tnop
        1:\tj\t1b
        /* see /src/util.c:12 for why */
        80000004:\t0000006f          \tj\t80000004 <_start+0x4>
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instructions.map(\.pc) == [0x8000_0000, 0x8000_0004])
        #expect(listing.sourceLocations.isEmpty)
        // A record is the whole line, but for objdump's discriminator.
        let records = AsmListingParser.parse("/src/a.c:12 (discriminator 3)\n/src/a.c:13 foo\n./b.c:4\nC:/w/c.c:5\n")
        #expect(records.sourceLocations.map(\.source) == [AsmSourceRef(file: "/src/a.c", line: 12), AsmSourceRef(file: "./b.c", line: 4),
                                                         AsmSourceRef(file: "C:/w/c.c", line: 5)])
    }

    @Test func eachSourceGuardHoldsOnItsOwn() {
        // An object file's listing (symbols at 0): source text whose address is past the symbol.
        let text = """
        Disassembly of section .text:

        00000000 <f>:
           0:\t00000013          \tnop
           4:\t00000013          \tnop
        2:\tj\t1b
           8:  addi a0, a0, 1
           8:\t00150513          \taddi\ta0,a0,1
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instructions.map(\.pc) == [0, 4, 8])
        #expect(listing.instruction(forPC: 8)?.encoding == 0x0015_0513)
    }

    @Test func aFunctionWithoutLineRecordsHasNoSource() {
        let text = """
        Disassembly of section .text:

        00000000 <f>:
        /src/f.c:3
           0:\t00000013          \tnop

        00000004 <crt>:
           4:\t00000013          \tnop
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instruction(forPC: 0)?.source == AsmSourceRef(file: "/src/f.c", line: 3))
        #expect(listing.instruction(forPC: 4)?.source == nil)
    }

    @Test func symbolAndOffsetPreferCode() {
        let text = """
        Disassembly of section .data:

        00000000 <f>:
           0:\t00000000          \t.word\t0x0

        Disassembly of section .text:

        00001000 <f>:
            1000:\t00000013          \tnop
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instruction(symbol: "f", offset: 0)?.pc == 0x1000)
    }

    @Test func lineRecordsGiveSourceLocations() throws {
        let gnu = try Self.parse("gnu-rv32-l.dis")
        let lui = try #require(gnu.instruction(forPC: 0x8000_0000))
        #expect(lui.source == AsmSourceRef(file: "/fixture/src/start.S", line: 6))
        let sum = try #require(gnu.instruction(forPC: 0x8000_004e))
        #expect(sum.source?.file == "/fixture/src/sum.c")
        // A function's first record comes after its label: the label resets it (CE's rule).
        let llvm = try Self.parse("llvm-rv32-l.dis")
        #expect(llvm.instruction(forPC: 0x8000_0000)?.source == AsmSourceRef(file: "/fixture/src/start.S", line: 6))
        #expect(!gnu.sourceLocations.isEmpty)
        #expect(llvm.sourceLocations.count == gnu.sourceLocations.count)
    }

    @Test func relocationsAreKeptAndAreNotInstructions() throws {
        let listing = try Self.parse("gnu-rv32-reloc-start-obj.dis")
        #expect(listing.relocations.contains { $0.pc == 0x10 && $0.type == "R_RISCV_CALL_PLT" && $0.data == "sum" })
        #expect(listing.instruction(forPC: 0x10)?.text == "auipc\tra,0x0")
        // `.L` labels are local: the global symbol carries on.
        let j = try #require(listing.instruction(forPC: 0x2e))
        #expect(j.symbol == "_start" && j.offset == 0x2e)
        #expect(listing.labels.map(\.name) == ["_start", ".Lpcrel_hi0", "after_gap"])
        let llvm = try Self.parse("llvm-rv32-reloc-obj.dis")
        #expect(llvm.relocations.contains { $0.pc == 0 && $0.type == "R_RISCV_PCREL_HI20" && $0.data == "table" })
        #expect(Self.places(llvm) == Self.places(try Self.parse("gnu-rv32-reloc-obj.dis")))
    }

    // MARK: llvm-objdump

    @Test func llvmAgreesWithGnu() throws {
        for (llvmName, gnuName) in [("llvm-rv32-code.dis", "gnu-rv32-code.dis"), ("llvm-rv64-code.dis", "gnu-rv64-code.dis"),
                                    ("llvm-rv32-all.dis", "gnu-rv32-all.dis")] {
            let llvm = try Self.parse(llvmName)
            let gnu = try Self.parse(gnuName)
            #expect(llvm.flavor == .llvm)
            if llvmName.contains("all") {
                // -D: llvm shows data as `.word`s, GNU as 16/32-bit instructions; code agrees.
                let code = { (l: AsmListing) in l.instructions.filter(\.isCode).map { "\($0.pc) \($0.encoding ?? 0) \($0.symbol ?? "")" } }
                #expect(code(llvm) == code(gnu))
                let word = try #require(llvm.instruction(forPC: 0x8000_1000))
                #expect(word.encoding == 0xdead_beef && word.size == 4 && !word.isCode)
            } else {
                #expect(Self.places(llvm) == Self.places(gnu), "\(llvmName)")
                #expect(llvm.instructions.map(\.encoding) == gnu.instructions.map(\.encoding), "\(llvmName)")
            }
        }
        let rv64 = try Self.parse("llvm-rv64-code.dis")
        #expect(rv64.labels.first?.address == 0x8000_0000)
        #expect(rv64.xlen == 64)
        let llvm = try Self.parse("llvm-rv32-code.dis")
        let bnez = try #require(llvm.instruction(forPC: 0x8000_000c))
        #expect(bnez.target == 0x8000_0008 && bnez.targetSymbol == "_start")
        for name in ["llvm-rv32-noraw.dis", "llvm-rv32-l.dis", "llvm-rv32-S.dis", "llvm-rv32-numeric-noaliases.dis"] {
            #expect(Self.places(try Self.parse(name)) == Self.places(llvm), "\(name)")
        }
    }

    @Test func spacedLittleEndianBytes() {
        // Older llvm-objdump releases print RISC-V instructions as bytes in memory order.
        let text = """
        a.elf:\tfile format elf32-littleriscv

        Disassembly of section .text:

        80000000 <_start>:
        80000000: 37 41 00 80  \tlui\tsp, 0x80004
        80000004: 01 45        \tli\ta0, 0x0
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instructions.map(\.encoding) == [0x8000_4137, 0x4501])
        #expect(listing.instructions.map(\.size) == [4, 2])
    }

    @Test func wrappedRawBytesJoinTheirInstruction() {
        // objdump wraps an instruction's bytes past its raw column onto a line of their own.
        let text = """
        Disassembly of section .text:

        00001000 <f>:
            1000:\t11 22 33 44 55 66 77 \tmovabs\t$0x1,%rax
            1007:\t88 99 \n    1009:\tc3                   \tret
        """
        let listing = AsmListingParser.parse(text)
        #expect(listing.instructions.count == 2)
        #expect(listing.instructions[0].size == 9)
        #expect(listing.instructions[0].encoding == nil)  // wider than 64 bits: not kept as a number
        #expect(listing.instructions[1].pc == 0x1009)
    }

    // MARK: lookups

    @Test func snapsFromALabelToItsFirstInstruction() throws {
        let text = try Self.fixture("gnu-rv32-code.dis")
        let listing = AsmListingParser.parse(text)
        let lines = text.components(separatedBy: "\n")
        let labelLine = try #require(lines.firstIndex(of: "8000004e <sum>:"))
        let snapped = try #require(listing.instructionLine(atOrAfter: labelLine))
        #expect(lines[snapped].hasPrefix("8000004e:"))
        #expect(listing.instructionLine(atOrAfter: snapped) == snapped)
        #expect(listing.instructionLine(atOrAfter: lines.count + 5) == nil)
    }

    @Test func symbolAndOffsetFindTheSameInstructionAfterARebuild() throws {
        let rv32 = try Self.parse("gnu-rv32-code.dis")
        let rv64 = try Self.parse("gnu-rv64-code.dis")
        // `sum` moved (rv64's `li sp` is two instructions); sum+0xc is the same `lw` in both.
        let old = try #require(rv32.instruction(symbol: "sum", offset: 0xc))
        let new = try #require(rv64.instruction(symbol: "sum", offset: 0xc))
        #expect(old.pc != new.pc)
        #expect(old.text == new.text)
        #expect(rv32.instruction(symbol: "nope", offset: 0) == nil)
        #expect(rv32.instruction(symbol: "sum", offset: 0x3) == nil)
        #expect(rv32.symbolize(pc: 0x8000_0056)?.symbol == "sum")
        #expect(rv32.symbolize(pc: 0x8000_0056)?.offset == 8)
    }

    @Test func truncatesPastItsLineCap() throws {
        let listing = AsmListingParser.parse(try Self.fixture("gnu-rv32-code.dis"), maxLines: 12)
        #expect(listing.truncated)
        #expect(listing.instructions.count == 5)  // lines 7–11
        #expect(!AsmListingParser.parse(try Self.fixture("gnu-rv32-code.dis")).truncated)
    }

    @Test func crlfAndEmptyText() {
        #expect(AsmListingParser.parse("").instructions.isEmpty)
        let listing = AsmListingParser.parse("Disassembly of section .text:\r\n\r\n00000000 <f>:\r\n   0:\t00000013          \tnop\r\n")
        #expect(listing.instructions.first?.text == "nop")
        #expect(listing.instructions.first?.line == 3)
    }

    // MARK: detection

    @Test func detectsListingsByContent() throws {
        for name in ["gnu-rv32-code.dis", "llvm-rv32-code.dis", "gnu-rv32-S.dis", "gnu-rv32-prefix.dis", "llvm-rv64-code.dis"] {
            #expect(AsmListingDetector.isListing(try Self.fixture(name)), "\(name)")
        }
        // No header, only instruction lines (a pasted excerpt saved as .s): eight are enough.
        let lines = try Self.fixture("gnu-rv32-code.dis").components(separatedBy: "\n").filter { $0.hasPrefix("8000") && $0.contains(":\t") }
        #expect(AsmListingDetector.isListing(lines.prefix(8).joined(separator: "\n")))
        #expect(!AsmListingDetector.isListing(lines.prefix(7).joined(separator: "\n")))
        // Real assembly source and C are not listings.
        #expect(!AsmListingDetector.isListing(try String(contentsOf: Self.fixtures.appendingPathComponent("src/start.S"), encoding: .utf8)))
        #expect(!AsmListingDetector.isListing(try String(contentsOf: Self.fixtures.appendingPathComponent("src/sum.c"), encoding: .utf8)))
        #expect(!AsmListingDetector.isListing("module top;\n  assign a = b;\nendmodule\n"))
        #expect(!AsmListingDetector.isListing(""))
    }

    /// The 4M-line cap's cost (ASM_LISTING_BENCH=1): a listing of that size, parsed once.
    @Test func parsesTheLineCapInReasonableTime() throws {
        guard ProcessInfo.processInfo.environment["ASM_LISTING_BENCH"] != nil else { return }
        var text = "Disassembly of section .text:\n\n00000000 <f>:\n"
        text.reserveCapacity(4_000_000 * 40)
        for i in 0..<3_999_990 { text += String(i * 4, radix: 16) + ":\t00000013          \tnop\n" }
        let clock = ContinuousClock()
        var listing: AsmListing?
        let elapsed = clock.measure { listing = AsmListingParser.parse(text) }
        #expect(listing?.instructions.count == 3_999_990)
        #expect(listing?.line(forPC: 0x400) == 3 + 0x100)
        print("4M-line listing parsed in \(elapsed)")
    }

    // MARK: a real course listing (read only; never committed)

    /// cpu on host-01: every PC its commit.log retired is an instruction of its program.dis, with the
    /// same encoding. Runs when ASM_LISTING_CPU_DIR holds program.dis and commit-pcs.txt
    /// (`awk '{print $4, $5}' commit.log | sort -u`).
    @Test func cpuListingHasEveryCommittedPC() throws {
        guard let dir = ProcessInfo.processInfo.environment["ASM_LISTING_CPU_DIR"] else { return }
        let base = URL(fileURLWithPath: dir)
        let listing = AsmListingParser.parse(try String(contentsOf: base.appendingPathComponent("program.dis"), encoding: .utf8))
        let pairs = try String(contentsOf: base.appendingPathComponent("commit-pcs.txt"), encoding: .utf8)
            .split(separator: "\n").map { $0.split(separator: " ") }
        var found = 0
        for pair in pairs where pair.count == 2 {
            let pc = try #require(UInt64(pair[0].dropFirst(2), radix: 16))
            let insn = try #require(UInt64(pair[1].dropFirst(3).dropLast(), radix: 16))
            let inst = listing.instruction(forPC: pc)
            #expect(inst?.isCode == true, "pc \(pair[0])")
            #expect(inst?.encoding == insn, "pc \(pair[0])")
            if inst?.encoding == insn { found += 1 }
        }
        #expect(found == pairs.count)
        print("cpu: \(found)/\(pairs.count) committed PCs found with their encodings; \(listing.instructions.count) instructions")
    }
}
